#!/usr/bin/env python3
"""Generate the model capability catalog used by shared host backends."""
import argparse
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
SOURCE = ROOT / "src" / "model_capabilities.json"
OUTPUT = ROOT / "src" / "model_capabilities.h"


def render(capabilities):
    lines = [
        "/* Generated by scripts/gen_model_capabilities.py; do not edit. */",
        "#ifndef BRAINCHOPC_MODEL_CAPABILITIES_H",
        "#define BRAINCHOPC_MODEL_CAPABILITIES_H",
        "",
    ]
    for index, (model, values) in enumerate(capabilities.items()):
        if set(values) != {"pve"} or not isinstance(values["pve"], bool):
            raise ValueError(f"{model}: expected one boolean pve capability")
        selector = "BC_MODEL_IS_" + model.upper()
        lines.append(("#if" if index == 0 else "#elif") +
                     f" defined({selector})")
        lines.append(f"#define BC_MODEL_SUPPORTS_PVE {int(values['pve'])}")
    lines += [
        "#else",
        '#error "select a model before including model_capabilities.h"',
        "#endif",
        "",
        "#endif",
        "",
    ]
    return "\n".join(lines)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    capabilities = json.loads(SOURCE.read_text())
    expected_models = {path.parent.name for path in
                       (ROOT / "src" / "models").glob("*/model.json")}
    if set(capabilities) != expected_models:
        raise SystemExit("model capability catalog does not match src/models")
    text = render(capabilities)
    if args.check:
        if not OUTPUT.is_file() or OUTPUT.read_text() != text:
            raise SystemExit(f"{OUTPUT} is stale; run {Path(__file__).name}")
        print(f"{OUTPUT.relative_to(ROOT)} is up to date")
    else:
        OUTPUT.write_text(text)
        print(f"wrote {OUTPUT.relative_to(ROOT)}")


if __name__ == "__main__":
    main()
